### Replace your method with this

```csharp
private async Task PopulateRoutedJobsAsync(DateOnly filterDate)
{
    try
    {
        var dispatched = await _dispatchViewModel.GetDispatchedJobsByDate(filterDate);
        var active     = await _dispatchViewModel.GetRoutableDevices();

        // Guard: need at least some dispatched jobs
        if (!(dispatched?.Success == true && dispatched.RecordsetCollection != null && dispatched.RecordsetCollection.Count > 0))
            return;

        var dispatchedJobs = dispatched.RecordsetCollection;

        // 1) Build the set of device GUIDs referenced by dispatched jobs
        var deviceGuidsFromJobs = new HashSet<Guid>(
            dispatchedJobs.Select(j => j.deliverDeviceGUID)
        );

        // 2) Build a lookup for active devices
        var activeLookup = (active?.Success == true && active.RecordsetCollection != null)
            ? active.RecordsetCollection.ToDictionary(d => d.DeviceGUID, d => d)
            : new Dictionary<Guid, RoutableDeviceDto>();

        // 3) Build the final device list for columns:
        //    - Include all devices referenced by jobs (active if found, or a NOT FOUND placeholder)
        //    - Also include any other active devices not already in the list
        var finalDevices = new List<RoutableDeviceDto>();

        foreach (var guid in deviceGuidsFromJobs)
        {
            if (activeLookup.TryGetValue(guid, out var found))
            {
                finalDevices.Add(found);
            }
            else
            {
                finalDevices.Add(new RoutableDeviceDto
                {
                    DeviceGUID = guid,
                    NickName   = "DEVICE NOT FOUND",
                    DriverGUID = Guid.Empty,
                    VehicleGUID= Guid.Empty
                });
            }
        }

        // Add any remaining active devices not in dispatched set
        if (activeLookup.Count > 0)
        {
            foreach (var kv in activeLookup)
            {
                if (!deviceGuidsFromJobs.Contains(kv.Key))
                    finalDevices.Add(kv.Value);
            }
        }

        // 4) Ensure columns exist for these devices (create missing only)
        EnsureTransportDeviceColumns(taskTransportation, finalDevices);

        // 5) Drop routed job cards into the matching columns
        foreach (var dispatch in dispatchedJobs)
        {
            // find matching column by Tag.DeviceGUID
            var column = taskTransportation.Columns
                .OfType<RadTaskBoardColumnElement>()
                .FirstOrDefault(c => (c.Tag as RoutableDeviceDto)?.DeviceGUID == dispatch.deliverDeviceGUID);

            if (column == null)
            {
                // Fallback by Title (in case your column factory used GUID as Title)
                column = taskTransportation.Columns
                    .OfType<RadTaskBoardColumnElement>()
                    .FirstOrDefault(c => string.Equals(c.Title, dispatch.deliverDeviceGUID.ToString(), StringComparison.OrdinalIgnoreCase));
            }

            if (column == null)
            {
                Log.Warning("No transport column found for dispatched job {JobGuid}. Device {DeviceGuid}", dispatch.JobGUID, dispatch.deliverDeviceGUID);
                continue;
            }

            // fetch job and create/add card
            var jobResult = await _dispatchViewModel.GetJobByID(dispatch.JobGUID);
            if (!(jobResult?.Success == true && jobResult.SingleRecord != null))
            {
                Log.Warning("Failed to fetch job {JobGuid} for routed placement.", dispatch.JobGUID);
                continue;
            }

            var card = _taskCardFactory.GetRoutedJobCard(jobResult.SingleRecord);
            if (card != null)
            {
                column.TaskCardCollection.Add(card);
            }
            else
            {
                Log.Warning("GetRoutedJobCard returned null for Job {JobGuid}", dispatch.JobGUID);
            }
        }

        // Optional: style columns again if needed
        foreach (RadTaskBoardColumnElement col in taskTransportation.Columns)
            ApplyStyle(col);
    }
    catch (Exception ex)
    {
        Log.Error(ex, "Error populating routed jobs.");
        throw;
    }
}
