/// <summary>
/// Creates missing transport columns for the given devices. 
/// Won't duplicate existing columns; matches by Tag.DeviceGUID (preferred) or Title==GUID.
/// </summary>
private void EnsureTransportDeviceColumns(RadTaskBoard board, IEnumerable<RoutableDeviceDto> devices)
{
    foreach (var device in devices)
    {
        var existing = board.Columns
            .OfType<RadTaskBoardColumnElement>()
            .FirstOrDefault(c => (c.Tag as RoutableDeviceDto)?.DeviceGUID == device.DeviceGUID)
            ?? board.Columns
                .OfType<RadTaskBoardColumnElement>()
                .FirstOrDefault(c => string.Equals(c.Title, device.DeviceGUID.ToString(), StringComparison.OrdinalIgnoreCase));

        if (existing != null)
            continue;

        var newCol = _taskColumnFactory.GetTransportColumn(device);
        if (newCol != null)
        {
            newCol.AllowDrop = true;
            newCol.Tag = device;
            board.Columns.Add(newCol);
        }
        else
        {
            Log.Warning("GetTransportColumn returned null for device {DeviceGuid}", device.DeviceGUID);
        }
    }
}
```

