        public void Attach(RadTaskBoard board)

        {

            ThrowIfDisposed();

            Detach();



            _board = board ?? throw new ArgumentNullException(nameof(board));



            if (_board.IsHandleCreated && _board.TaskBoardElement != null)

            {

                WireNow();

            }

            else

            {

                _board.HandleCreated += Board_HandleCreated;

            }

