        var all = await _repository.FindCollectionAsync(ct); // fetch all
        var getDate = pickupDateSelector.Compile();
        var filtered = all.Where(m => getDate(m).HasValue && getDate(m)!.Value == dateFilter).ToList();
        return _mapper.Map<List<TDto>>(filtered);
    }
    catch (Exception ex)
    {
        Log.Error(ex, "Error retrieving {ModelType} records for pickup date {Date}.",
