        {
            // Repo exposes a predicate that the provider can translate (Expression<Func<...>>)
            var models = await _repo.FindAsync(j => j.PickupDate == date, ct);

            var result = models?.Count > 0
                ? _mapper.Map<List<JobDto>>(models)
                : new List<JobDto>();

            Log.Information("Retrieved {Count} jobs for pickup date {Date}.", result.Count, date);
            return result;
        }
        catch (Exception ex)
