            var jobs = await _processingJobHandler.GetByPickupDate(filterDate, ct);
            if (jobs is null || jobs.Count == 0) return NotFound();
            return Ok(jobs);
        }
        catch (Exception ex)
        {
            Log.Error(ex, "Unexpected error in GetByPickupDateRoute for {PickupDate}", filterDate);
            return StatusCode(StatusCodes.Status500InternalServerError, "An unexpected error occurred.");
        }
    }
}
```

