You’ve got two separate issues here:

1) `dispatchDetails` is **double-encoded** (a JSON string that itself contains JSON).  
2) `routeDate` comes as `"2025-09-01T00:00:00"` which **won’t bind to `DateOnly`** unless you add a converter.

You can fix either on the API or on the desktop. Here’s how to make the **desktop client** robust to both.

# Desktop-side, robust deserialization

## 1) Models
```csharp
public sealed class DispatchDto
{
    public Guid DispatchGUID { get; set; }
    public Guid JobGUID { get; set; }

    // We'll convert string-or-object into this strong type via a custom converter.
    public DispatchDetails DispatchDetails { get; set; }

    public Guid DeliverDeviceGUID { get; set; }
    public Guid SendingDeviceGUID { get; set; }

    public DateOnly RouteDate { get; set; }  // stays DateOnly, we add a converter
    public bool Received { get; set; }
    public bool Sent { get; set; }
    public Guid Id { get; set; }
    public string RowVersion { get; set; } = "";
}

public sealed class DispatchDetails
{
    public Guid VehicleGUID { get; set; }
    public string? DeliveryPriority { get; set; }
    public TimeSpan? ExpectedDepartureTime { get; set; }
    public TimeSpan? ExpectedArrivalTime { get; set; }
    public DateOnly? ExpectedDepartureDate { get; set; }
    public DateOnly? ExpectedArrivalDate { get; set; }
    public Address? PickupAddress { get; set; }
    public Address? DeliveryAddress { get; set; }
    public string? GeoLocation { get; set; }
    public List<object>? AccessorialList { get; set; }
    public List<object>? JobDocuments { get; set; }
    public string? Cautions { get; set; }
}

public sealed class Address
{
    public string? StreetAddress { get; set; }
    public string? City { get; set; }
    public string? State { get; set; }
    public string? ZipCode { get; set; }
    public string? GeoLocation { get; set; }
}
```

## 2) Converters
```csharp
using System.Text.Json;
using System.Text.Json.Serialization;

public sealed class DateOnlyJsonConverter : JsonConverter<DateOnly>
{
    public override DateOnly Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        // Accept "yyyy-MM-dd" or a full datetime "yyyy-MM-ddTHH:mm:ss"
        var s = reader.GetString();
        if (string.IsNullOrWhiteSpace(s)) return default;

        if (DateTime.TryParse(s, out var dt)) return DateOnly.FromDateTime(dt);
        // final attempt: direct DateOnly parse (if API ever sends pure date)
        if (DateOnly.TryParse(s, out var d)) return d;

        throw new JsonException($"Invalid DateOnly: {s}");
    }

    public override void Write(Utf8JsonWriter writer, DateOnly value, JsonSerializerOptions options)
        => writer.WriteStringValue(value.ToString("yyyy-MM-dd"));
}

public sealed class NullableDateOnlyJsonConverter : JsonConverter<DateOnly?>
{
    private static readonly DateOnlyJsonConverter _inner = new();

    public override DateOnly? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        if (reader.TokenType == JsonTokenType.Null) return null;
        return _inner.Read(ref reader, typeof(DateOnly), options);
    }

    public override void Write(Utf8JsonWriter writer, DateOnly? value, JsonSerializerOptions options)
    {
        if (value is null) { writer.WriteNullValue(); return; }
        _inner.Write(writer, value.Value, options);
    }
}

/// <summary>
/// Handles dispatchDetails being either an object OR a JSON string of an object.
/// </summary>
public sealed class DispatchDetailsConverter : JsonConverter<DispatchDetails>
{
    public override DispatchDetails? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        // If it's a JSON string, parse the inner JSON.
        if (reader.TokenType == JsonTokenType.String)
        {
            var json = reader.GetString();
            if (string.IsNullOrWhiteSpace(json)) return new DispatchDetails();
            var innerOptions = CreateInnerOptions(options);
            return JsonSerializer.Deserialize<DispatchDetails>(json, innerOptions);
        }

        // If it's already an object, deserialize normally.
        if (reader.TokenType == JsonTokenType.StartObject)
        {
            var innerOptions = CreateInnerOptions(options);
            using var doc = JsonDocument.ParseValue(ref reader);
            var raw = doc.RootElement.GetRawText();
            return JsonSerializer.Deserialize<DispatchDetails>(raw, innerOptions);
        }

        throw new JsonException("dispatchDetails is neither string nor object.");
    }

    public override void Write(Utf8JsonWriter writer, DispatchDetails value, JsonSerializerOptions options)
    {
        // Write as proper object (not string) going forward
        var innerOptions = CreateInnerOptions(options);
        JsonSerializer.Serialize(writer, value, innerOptions);
    }

    private static JsonSerializerOptions CreateInnerOptions(JsonSerializerOptions baseOptions)
    {
        var o = new JsonSerializerOptions(baseOptions);
        // Ensure DateOnly? inside details works too
        o.Converters.Add(new DateOnlyJsonConverter());
        o.Converters.Add(new NullableDateOnlyJsonConverter());
        return o;
    }
}
```

## 3) Register converters and deserialize
```csharp
var options = new JsonSerializerOptions
{
    PropertyNameCaseInsensitive = true
};
options.Converters.Add(new DateOnlyJsonConverter());
options.Converters.Add(new NullableDateOnlyJsonConverter());
options.Converters.Add(new DispatchDetailsConverter());

var list = JsonSerializer.Deserialize<List<DispatchDto>>(json, options);
```

This succeeds whether the API sends:
- `routeDate: "2025-09-01T00:00:00"` or just `"2025-09-01"`
- `dispatchDetails` as a **string** containing JSON (your current payload) **or** as a proper **object** (future fix)

---

# API-side (longer-term clean fix)
- Stop double-encoding: return `dispatchDetails` as a **JSON object**, not a JSON string.
- If you keep `DateOnly` in your server model, add an EF **value converter** (DateOnly ⇄ DateTime at midnight) so the DB stores `00:00:00` and you serialize `yyyy-MM-dd`.

```csharp
// EF model config
builder.Entity<Dispatch>()
    .Property(e => e.RouteDate)
    .HasConversion(v => v.ToDateTime(TimeOnly.MinValue),
                   v => DateOnly.FromDateTime(v));
```

